test('maxBytes validation: omitted is unlimited; non-positive-integer throws TypeError synchronously', () => {
  const dirsLocal = [];
  const make = (maxBytes) => {
    const dir = `/tmp/replay-bus-quota-check-${Math.random().toString(36).slice(2)}`;
    dirsLocal.push(dir);
