            }
            if (!req || req.s === sessionId) {
              rmSync(path.join(dir, name), { force: true });
            }
          }
        }
        const lease = readLeaseLocked();
        if (!lease) return;
        const sessions = lease.sessions.filter((s) => s.id !== sessionId);

